import{_ as a,o as t,c as s,a5 as n}from"./chunks/framework.pJebtgMf.js";const m=JSON.parse('{"title":"AI 动态 · 2026-08-31","description":"","frontmatter":{"title":"AI 动态 · 2026-08-31","date":"2026-08-31T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-31.md","filePath":"news/2026-08/ai-news-2026-08-31.md","lastUpdated":null}'),r={name:"news/2026-08/ai-news-2026-08-31.md"};function i(o,e,l,c,p,d){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-动态-·-2026-08-31" tabindex="-1">AI 动态 · 2026-08-31 <a class="header-anchor" href="#ai-动态-·-2026-08-31" aria-label="Permalink to &quot;AI 动态 · 2026-08-31&quot;">​</a></h1><blockquote><p>截至 2026-08-31。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="欧盟将-chatgpt-列为超大型在线搜索引擎-面临更严监管" tabindex="-1">欧盟将 ChatGPT 列为超大型在线搜索引擎，面临更严监管 <a class="header-anchor" href="#欧盟将-chatgpt-列为超大型在线搜索引擎-面临更严监管" aria-label="Permalink to &quot;欧盟将 ChatGPT 列为超大型在线搜索引擎，面临更严监管&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-08-31">2026-08-31</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/f94c0839add3.png" alt="配图"></p><p>欧盟委员会将 OpenAI 的 ChatGPT 认定为《数字服务法案》（DSA）下的“超大型在线搜索引擎”，与 Reddit 和 Roblox 一同面临更严格的合规要求。新规将重点管控其对未成年人、心理健康及非法内容传播的风险，并限制定向广告。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/986682/openai-chatgpt-eu-dsa" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="instagram-打击伪装成人类的-ai-账号-引入新标签" tabindex="-1">Instagram 打击伪装成人类的 AI 账号，引入新标签 <a class="header-anchor" href="#instagram-打击伪装成人类的-ai-账号-引入新标签" aria-label="Permalink to &quot;Instagram 打击伪装成人类的 AI 账号，引入新标签&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-08-31">2026-08-31</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/55cd129a495b.jpg" alt="配图"></p><p>Instagram 宣布将打击平台上伪装成真人的 AI 生成账号，并将“AI creator”标签更名为“AI-generated profile”，以更清晰地标识非人类账号。平台将限制未自我标识的 AI 账号的推荐范围，以提升透明度。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/986593/instagram-addresses-fake-ai-profile-slop" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="debian-投票决定不禁止-ai-生成的代码贡献" tabindex="-1">Debian 投票决定不禁止 AI 生成的代码贡献 <a class="header-anchor" href="#debian-投票决定不禁止-ai-生成的代码贡献" aria-label="Permalink to &quot;Debian 投票决定不禁止 AI 生成的代码贡献&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-08-31">2026-08-31</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/cec82f2875f7.jpg" alt="配图"></p><p>Debian 项目投票决定，允许开发者在其 Linux 发行版的开发、维护和文档中使用 AI 工具。新政策强调，AI 生成的贡献将遵循与人工贡献相同的质量标准，不设额外限制，但也不享有特殊豁免。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/986789/linux-debian-generative-ai-policy" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="openclaw-2-0-发布-会话迁移至-sqlite-启动速度大幅提升" tabindex="-1">OpenClaw 2.0 发布：会话迁移至 SQLite，启动速度大幅提升 <a class="header-anchor" href="#openclaw-2-0-发布-会话迁移至-sqlite-启动速度大幅提升" aria-label="Permalink to &quot;OpenClaw 2.0 发布：会话迁移至 SQLite，启动速度大幅提升&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Help Net Security</span><time datetime="2026-08-31">2026-08-31</time></p><p>开源 AI Agent 项目 OpenClaw 发布 2.0 版本，核心变化是将会话存储迁移至 SQLite，并实现了 575 毫秒的控制 UI 启动速度，同时引入每个网关单一信任边界的安全模型，提升了数据管理与安全性。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMic0FVX3lxTE9ZbTVrWVRjVk9kMnUtczdiSmI3WXB5Nl92Q2kzR2hGbURkMENJazlhVXVHMXpWblBMeWhXdnBKMkxWdk5TUGN6UEQ4TGIzczJCUi0zaTBwb01JeXpkZ3psX2JHRmRUZU9QY3lqMlRMdTRTajA?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="startlux-27b-本地大模型通过-mcp-universe-测评-综合性能第二" tabindex="-1">StartLux-27B 本地大模型通过 MCP-Universe 测评，综合性能第二 <a class="header-anchor" href="#startlux-27b-本地大模型通过-mcp-universe-测评-综合性能第二" aria-label="Permalink to &quot;StartLux-27B 本地大模型通过 MCP-Universe 测评，综合性能第二&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">36氪</span><time datetime="2026-08-31">2026-08-31</time></p><p>中国信通院公布的可信 AI 大模型 MCP 专项测试中，StartLux 的 27B 参数模型综合排名第二，超越 284B 的 DeepSeek-V4-Flash，进入万亿参数模型能力区间。测试涵盖导航、搜索、浏览器自动化等 6 类任务。</p><p class="news-entry-source"><a href="https://36kr.com/p/3963345222147335?f=rss" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="腾讯发布-hy4-预览版模型-部分测试超越-gpt-5-6-sol" tabindex="-1">腾讯发布 Hy4 预览版模型，部分测试超越 GPT-5.6 Sol <a class="header-anchor" href="#腾讯发布-hy4-预览版模型-部分测试超越-gpt-5-6-sol" aria-label="Permalink to &quot;腾讯发布 Hy4 预览版模型，部分测试超越 GPT-5.6 Sol&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GIGAZINE</span><time datetime="2026-08-31">2026-08-31</time></p><p>腾讯发布了名为 &#39;Hy4 preview&#39; 的 AI 模型，据称在部分测试中超越了 GPT-5.6 Sol，并同步推出了更轻量的 1-bit 量化版本，体积为 213GB，兼顾了性能与部署成本。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMibkFVX3lxTE56aE9HUjBQM3I5MktMVGlzZG9kaXc1MVEtVEVwREdnNnhxd2R0cmpuaVhsWXNjTzZVZ2lpUDBTZXlEcFByUFNCUUdKTmxUTW1NcW93cURnNEdBMW9YQTFpaXBKLTNzcHgtcnNKZ0Fn?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="claude-code-拒用-agents-md-标准-遭-shopify-ceo-公开威胁禁用" tabindex="-1">Claude Code 拒用 AGENTS.md 标准，遭 Shopify CEO 公开威胁禁用 <a class="header-anchor" href="#claude-code-拒用-agents-md-标准-遭-shopify-ceo-公开威胁禁用" aria-label="Permalink to &quot;Claude Code 拒用 AGENTS.md 标准，遭 Shopify CEO 公开威胁禁用&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-31">2026-08-31</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/ad986cca60da.png" alt="配图"></p><p>Anthropic 的 Claude Code 因拒绝支持已被超 6 万个项目采用的 AGENTS.md 标准，而坚持使用自家 CLAUDE.md，引发 Shopify CEO Tobi Lütke 的公开批评，并威胁在内部禁用该工具，凸显 AI 编程工具标准化之争。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/GuFWNd24Ww5AFlrXxTBo?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="css-random-函数跨浏览器-polyfill-实践" tabindex="-1">CSS random() 函数跨浏览器 Polyfill 实践 <a class="header-anchor" href="#css-random-函数跨浏览器-polyfill-实践" aria-label="Permalink to &quot;CSS random() 函数跨浏览器 Polyfill 实践&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">CSS-Tricks</span><time datetime="2026-08-31">2026-08-31</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/527d83de619f.jpg" alt="配图"></p><p>CSS-Tricks 发布文章，探讨如何为即将到来的 CSS random() 函数创建可在所有浏览器中工作的 polyfill。文章详细介绍了实现过程，为开发者提供了在原生支持落地前使用该函数的可行方案。</p><p class="news-entry-source"><a href="https://css-tricks.com/css-random-function-polyfill/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div>',8)])])}const u=a(r,[["render",i]]);export{m as __pageData,u as default};
